"""Hardware-free regression tests for CircuitPython-compatible colorwheel output."""

from array import array

import pytest
import rainbowio

from rainbowio import colorwheel

# Native reference: shared-module/rainbowio/__init__.c in CircuitPython commit
# 199e64fa5421be415d22edb66d799ad555cac256. Expected colors are fixed vectors,
# not values generated by duplicating the implementation under test.


@pytest.mark.parametrize(
    "hue, expected",
    [
        (0, 0xFF0000),
        (1, 0xFC0300),
        (84, 0x03FC00),
        (85, 0x00FF00),
        (86, 0x00FC03),
        (169, 0x0003FC),
        (170, 0x0000FF),
        (171, 0x0300FC),
        (254, 0xFC0003),
        (255, 0xFF0000),
        (256, 0xFF0000),
        (257, 0xFC0300),
        (345, 62220),
        (512, 0xFF0000),
    ],
)
def test_colorwheel_integer_colors_and_wrapping(hue, expected):
    """Keep the existing palette while wrapping hues past one revolution."""
    assert colorwheel(hue) == expected
    assert isinstance(colorwheel(hue), int)


@pytest.mark.parametrize(
    "hue, expected",
    [
        (0.5, 0xFE0100),
        (84.5, 0x02FD00),
        (84.75, 0x01FE00),
        (85.5, 0x00FE01),
        (169.5, 0x0002FD),
        (170.5, 0x0100FE),
        (254.5, 0xFD0002),
        (255.5, 0xFF0000),
        (255.75, 0xFF0000),
        (256.5, 0xFE0100),
        (340.5, 0x02FD00),
    ],
)
def test_colorwheel_fractional_hues(hue, expected):
    """Native colorwheel truncates the channel after scaling, not the input hue."""
    assert colorwheel(hue) == expected


@pytest.mark.parametrize("hue", range(256))
def test_colorwheel_repeats_every_256(hue):
    """Each byte-sized integer hue repeats over multiple revolutions."""
    assert colorwheel(hue) == colorwheel(hue + 256) == colorwheel(hue + 1024)


@pytest.mark.parametrize("hue", [-1, -85, -256])
def test_colorwheel_negative_integers_remain_black(hue):
    """Preserve the legacy negative-integer result rather than emulating C casts."""
    assert colorwheel(hue) == 0


@pytest.mark.parametrize(
    "hue",
    [
        None,
        "1",
        "84.5",
        b"1",
        bytearray(b"1"),
        memoryview(b"84.5"),
        array("b", b"84.5"),
    ],
)
def test_colorwheel_requires_numeric_input(hue):
    """The native binding accepts numbers, not text parsed as a number."""
    with pytest.raises(TypeError):
        colorwheel(hue)


def test_colorwheel_accepts_float_conversion():
    """Honor the same floating-point conversion protocol as the native binding."""

    class Hue:
        """A numeric hue providing the float protocol."""

        def __float__(self):
            return 84.5

    assert colorwheel(Hue()) == 0x02FD00


@pytest.mark.parametrize("hue, expected", [(False, 0xFF0000), (True, 0xFC0300)])
def test_colorwheel_micropython_boolean_hues(monkeypatch, hue, expected):
    """MicroPython bool has no int parent or __float__; both values are numeric."""
    builtin_isinstance = isinstance
    builtin_hasattr = hasattr

    def micropython_isinstance(value, classes):
        if builtin_isinstance(value, bool):
            return bool in classes
        return builtin_isinstance(value, classes)

    def micropython_hasattr(value, name):
        if builtin_isinstance(value, bool) and name == "__float__":
            return False
        return builtin_hasattr(value, name)

    # Model these two source-verified interpreter differences locally, not by
    # altering CPython's global builtins. This is not a MicroPython VM test.
    monkeypatch.setattr(rainbowio, "isinstance", micropython_isinstance, raising=False)
    monkeypatch.setattr(rainbowio, "hasattr", micropython_hasattr, raising=False)
    assert colorwheel(hue) == expected
